from typing import Dict, TypedDict
from collections import deque




class PostInfo(TypedDict):
    post_id: str
    author_id: str
    title: str
    content: str
    subreddit_id: str
    timestamp: float
    upvotes: int
    downvotes: int
    comment_count: int


class CommentInfo(TypedDict):
    comment_id: str
    post_id: str
    parent_comment_id: str  # None if top-level comment
    author_id: str
    content: str
    timestamp: float
    upvotes: int
    downvotes: int
    edited_flag: bool


class UserInfo(TypedDict):
    _id: str
    username: str
    language_preference: str
    account_age: int  # in days
    karma: int


class SessionInfo(TypedDict):
    session_id: str
    user_id: str
    language_setting: str
    active_subreddit: str
    sort_preference: str  # e.g., 'new', 'top', 'hot'


class SubredditInfo(TypedDict):
    subreddit_id: str
    name: str
    language: str
    moderator_list: list[str]
    content_policy: str


class RedditSocialMediaPlatform:
    def __init__(self):
        """
        Simulates the stateful environment of the Reddit social media platform,
        maintaining posts, comments, users, sessions, and subreddits.
        """

        # Posts: {post_id: PostInfo}
        self.posts: Dict[str, PostInfo] = {}

        # Comments: {comment_id: CommentInfo}
        self.comments: Dict[str, CommentInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Sessions: {session_id: SessionInfo}
        self.sessions: Dict[str, SessionInfo] = {}

        # Subreddits: {subreddit_id: SubredditInfo}
        self.subreddits: Dict[str, SubredditInfo] = {}

        # Constraints reminder:
        # - Comments must be retrievable by sort criteria (e.g., 'new' by timestamp, 'top' by upvotes)
        # - Language settings (user/session) affect content rendering and interface localization
        # - Nested comment threads preserved via parent_comment_id
        # - A post belongs to exactly one subreddit
        # - Users can update language preferences, influencing future content delivery

    def get_post_by_id(self, post_id: str) -> dict:
        """
        Retrieve detailed information about a post using its unique post_id.

        Args:
            post_id (str): The unique identifier of the post.

        Returns:
            dict: {
                "success": True,
                "data": PostInfo  # Full post information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Post not found"
            }

        Constraints:
            - The post_id must correspond to an existing post in the system.
        """
        if not post_id:
            return {"success": False, "error": "Post ID cannot be empty"}

        post = self.posts.get(post_id)
        if post is None:
            return {"success": False, "error": "Post not found"}

        return {"success": True, "data": post}

    def get_subreddit_by_id(self, subreddit_id: str) -> dict:
        """
        Fetch metadata of a subreddit by its unique identifier.

        Args:
            subreddit_id (str): The ID of the subreddit to retrieve.

        Returns:
            dict: {
                "success": bool,
                "data": SubredditInfo  # If successful
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The subreddit_id must correspond to an existing subreddit.
        """
        if not subreddit_id:
            return {"success": False, "error": "Subreddit ID cannot be empty"}

        subreddit_info = self.subreddits.get(subreddit_id)
        if subreddit_info is None:
            return {"success": False, "error": "Subreddit not found"}

        return {"success": True, "data": subreddit_info}

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve the profile information of a user by their user ID.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # The user's profile information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "User not found"
            }

        Constraints:
            - The user_id must correspond to an existing user in the system.
        """
        user = self.users.get(user_id)
        if not user:
            return {"success": False, "error": "User not found"}

        return {"success": True, "data": user}

    def get_session_by_id(self, session_id: str) -> dict:
        """
        Retrieve the session information for the given session ID.

        Args:
            session_id (str): The unique identifier of the session to retrieve.

        Returns:
            dict: {
                "success": bool,
                "data": SessionInfo   # If successful
            }
            or {
                "success": False,
                "error": str           # If session not found
            }

        Constraints:
            - The session must exist in the system.
        """
        session = self.sessions.get(session_id)
        if session is None:
            return {"success": False, "error": "Session not found"}

        return {"success": True, "data": session}

    def list_comments_by_post(self, post_id: str) -> dict:
        """
        Retrieve all comments associated with the given post_id.

        Args:
            post_id (str): The ID of the post to retrieve comments for.

        Returns:
            dict: {
                "success": True,
                "data": List[CommentInfo]  # List of comments linked to the post (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Only if input validation fails (though post_id as str is always valid)
            }

        Note:
            - Returns all comments regardless of nesting level (top-level or replies).
            - Does not require the post to exist; returns empty list if no matching comments.
            - Sorting is not applied here; use `list_comments_sorted` for ordered results.
        """
        if not isinstance(post_id, str):
            return {"success": False, "error": "post_id must be a string"}

        result = [
            comment for comment in self.comments.values()
            if comment["post_id"] == post_id
        ]

        return {
            "success": True,
            "data": result
        }

    def list_comments_sorted(self, post_id: str, sort_by: str) -> dict:
        """
        Retrieve all comments for a given post sorted by a specified criterion.

        Args:
            post_id (str): The ID of the post to retrieve comments for.
            sort_by (str): Sorting criterion. Supported values: 'new', 'top', 'hot'.
                           - 'new': sort by timestamp descending (newest first)
                           - 'top': sort by upvotes descending
                           - 'hot': currently treated as 'top'; could be enhanced with time-based scoring

        Returns:
            dict: {
                "success": bool,
                "data": List[CommentInfo]  # List of CommentInfo dicts sorted by criterion (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error (e.g., post not found, invalid sort criterion)
            }

        Constraints:
            - Only comments belonging to the given post are returned.
            - Sorting must be applied based on the specified valid criterion.
            - Nested comment relationships are preserved in data but not structured into threads here.
        """
        # Validate post_id
        if post_id not in self.posts:
            return {"success": False, "error": "Post not found"}

        # Supported sort methods
        if sort_by not in ['new', 'top', 'hot']:
            return {"success": False, "error": "Invalid sort criterion. Supported: 'new', 'top', 'hot'"}

        # Filter comments by post_id
        post_comments = [
            comment for comment in self.comments.values()
            if comment["post_id"] == post_id
        ]

        # Sort based on criterion
        if sort_by == 'new':
            sorted_comments = sorted(post_comments, key=lambda c: c["timestamp"], reverse=True)
        elif sort_by == 'top':
            sorted_comments = sorted(post_comments, key=lambda c: c["upvotes"], reverse=True)
        elif sort_by == 'hot':
            # For simplicity, 'hot' uses same logic as 'top'
            sorted_comments = sorted(post_comments, key=lambda c: c["upvotes"], reverse=True)
        else:
            # This block should not be reached due to prior validation
            sorted_comments = post_comments

        return {"success": True, "data": sorted_comments}

    def get_comment_thread(self, comment_id: str) -> dict:
        """
        Retrieve a nested comment thread starting from the specified comment, 
        preserving the hierarchical structure without nested function definitions.

        Args:
            comment_id (str): The ID of the comment to start the thread from (can be top-level or nested).

        Returns:
            dict: {
                "success": True,
                "data": CommentInfo with "replies" field added (nested dicts with children under "replies")
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. comment not found
            }

        Note:
            The returned structure adds a "replies" key (list of nested comment objects) to each comment,
            recursively representing the tree of responses beneath the given comment.
            This function contains no nested functions.
        """
        # Check for existence of the requested comment
        if comment_id not in self.comments:
            return {"success": False, "error": "Comment not found"}

        # Build a mapping from parent_comment_id to list of child comments
        comment_tree: Dict[str, list] = {}
        for cid, comment in self.comments.items():
            parent_id = comment["parent_comment_id"]
            if parent_id not in comment_tree:
                comment_tree[parent_id] = []
            comment_tree[parent_id].append(comment)

        # Iterative emulation of recursion for hierarchy construction:
        # Each item in 'nodes_to_expand' is a tuple:
        # (current_comment_dict, parent_comment_id, replies_list_to_fill)

        # Create the root node
        root_comment = self.comments[comment_id].copy()
        root_comment["replies"] = []

        # Use a stack/queue for iterative tree walk
        nodes_to_expand = deque()
        nodes_to_expand.append((root_comment, root_comment["comment_id"], root_comment["replies"]))

        while nodes_to_expand:
            node_dict, node_comment_id, replies_list = nodes_to_expand.popleft()
            children = comment_tree.get(node_comment_id, [])
            for child in children:
                child_copy = child.copy()
                child_copy["replies"] = []
                replies_list.append(child_copy)
                # Expand this child node recursively
                nodes_to_expand.append((child_copy, child_copy["comment_id"], child_copy["replies"]))

        return {"success": True, "data": root_comment}

    def get_language_context(self, session_id: str) -> dict:
        """
        Determine the effective language setting for content localization by first checking
        the session's language setting, and falling back to the user's language preference.

        Args:
            session_id (str): The ID of the session to resolve language context for.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "language": str,        # The resolved language code (e.g., "en", "es")
                    "source": str           # Either "session" or "user", indicating where the language was set
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., session not found, user not found, no language set
            }

        Constraints:
            - The language setting is first taken from the session.
            - If not set in session, it falls back to the user's language_preference.
            - If neither is available, the operation fails.
        """
        session = self.sessions.get(session_id)
        if not session:
            return {"success": False, "error": "Session not found"}

        # Check session language setting
        if session.get("language_setting"):
            return {
                "success": True,
                "data": {
                    "language": session["language_setting"],
                    "source": "session"
                }
            }

        # Fall back to user's language preference
        user_id = session.get("user_id")
        if not user_id:
            return {"success": False, "error": "Session has no associated user"}

        user = self.users.get(user_id)
        if not user:
            return {"success": False, "error": "User associated with session not found"}

        language_pref = user.get("language_preference")
        if not language_pref:
            return {"success": False, "error": "User has no language preference set"}

        return {
            "success": True,
            "data": {
                "language": language_pref,
                "source": "user"
            }
        }

    def get_active_subreddit_context(self, session_id: str) -> dict:
        """
        Retrieve the currently active subreddit in the given session for contextual filtering.

        Args:
            session_id (str): The unique identifier of the user session.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "active_subreddit": str or None  # The subreddit_id currently active, if any
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. session does not exist
            }

        Constraints:
            - The session must exist in the system.
            - The active_subreddit value may be None or a valid subreddit_id.
        """
        if session_id not in self.sessions:
            return {"success": False, "error": "Session does not exist"}

        session = self.sessions[session_id]
        return {
            "success": True,
            "data": {
                "active_subreddit": session["active_subreddit"]
            }
        }

    def set_session_language(self, session_id: str, language: str) -> dict:
        """
        Update the language setting of a session to influence content rendering and interface localization.

        Args:
            session_id (str): The unique identifier of the session.
            language (str): The language code (e.g., 'en', 'es') to set for the session.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. session not found
            }

        Constraints:
            - The session must exist in the system.
            - The language setting affects content rendering and interface localization.
        """
        if session_id not in self.sessions:
            return {"success": False, "error": "Session not found"}

        self.sessions[session_id]["language_setting"] = language
        return {"success": True, "message": "Session language setting updated"}

    def set_session_sort_preference(self, session_id: str, sort_preference: str) -> dict:
        """
        Change the default sort order used when retrieving posts or comments in the session.

        Args:
            session_id (str): The unique identifier of the session to update.
            sort_preference (str): The new sort preference (e.g., 'hot', 'top', 'new', 'controversial').

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. session not found
            }

        Constraints:
            - The session must exist in the system.
            - The sort_preference affects subsequent content retrieval operations.
        """
        if session_id not in self.sessions:
            return {"success": False, "error": "Session not found"}

        self.sessions[session_id]["sort_preference"] = sort_preference
        return {"success": True, "message": "Sort preference updated successfully"}

    def update_user_language_preference(self, user_id: str, new_language: str) -> dict:
        """
        Update a user's preferred language, which affects future content delivery and localization.

        Args:
            user_id (str): The unique identifier of the user.
            new_language (str): The new language preference to set (e.g., 'en', 'es').

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The user must exist in the system.
            - The updated language preference influences future content rendering and interface localization.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User not found."}

        self.users[user_id]["language_preference"] = new_language
        return {"success": True, "message": "User language preference updated successfully."}

    def edit_comment_content(self, comment_id: str, new_content: str) -> dict:
        """
        Update the content of an existing comment and mark it as edited.

        Args:
            comment_id (str): The unique identifier of the comment to edit.
            new_content (str): The new text content to set for the comment.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. comment not found
            }

        Constraints:
            - The comment must exist in the system.
            - After edit, the comment's 'edited_flag' must be set to True.
        """
        if comment_id not in self.comments:
            return { "success": False, "error": "Comment not found" }

        comment = self.comments[comment_id]
        comment["content"] = new_content
        comment["edited_flag"] = True

        return { "success": True, "message": "Comment content updated and marked as edited." }

    def switch_active_subreddit(self, session_id: str, new_subreddit_id: str) -> dict:
        """
        Change the active subreddit in the current session to navigate between communities.

        Args:
            session_id (str): The ID of the session to update.
            new_subreddit_id (str): The ID of the subreddit to set as active.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of subreddit switch
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., session or subreddit not found)
            }

        Constraints:
            - The session must exist.
            - The target subreddit must exist in the platform.
            - After switching, the session's active_subreddit reflects the new subreddit.
        """
        if not session_id:
            return { "success": False, "error": "Session ID is required" }

        if not new_subreddit_id:
            return { "success": False, "error": "New subreddit ID is required" }

        if session_id not in self.sessions:
            return { "success": False, "error": "Session does not exist" }

        if new_subreddit_id not in self.subreddits:
            return { "success": False, "error": "Subreddit does not exist" }

        # Update the active subreddit
        self.sessions[session_id]["active_subreddit"] = new_subreddit_id

        return {
            "success": True,
            "message": f"Active subreddit switched to {new_subreddit_id}"
        }

    def refresh_session_context(self, session_id: str) -> dict:
        """
        Reset or update session metadata to reflect current user preferences and subreddit settings.

        Args:
            session_id (str): The unique identifier of the session to refresh.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Describes outcome; included only if success=True
            } or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The session must exist.
            - The associated user must exist.
            - The active_subreddit in the session must exist.
            - Language and sort preferences are refreshed based on user and subreddit context.
        """
        if session_id not in self.sessions:
            return {"success": False, "error": "Session does not exist"}

        session = self.sessions[session_id]

        user_id = session["user_id"]
        if user_id not in self.users:
            return {"success": False, "error": "Associated user does not exist"}

        user = self.users[user_id]
        active_subreddit_id = session["active_subreddit"]

        if active_subreddit_id not in self.subreddits:
            return {"success": False, "error": "Active subreddit does not exist"}

        # Update session context based on current user and subreddit
        # Refresh language: session language may follow user preference
        session["language_setting"] = user["language_preference"]

        # No change to sort_preference unless default reset needed — not required here
        # Ensure active_subreddit is still valid (already checked)

        # Update timestamp not tracked in session, so no timestamp update

        return {"success": True, "message": "Session context refreshed successfully."}

