def switch_active_subreddit(self, session_id: str, new_subreddit_id: str) -> dict:
    """
    Change the active subreddit in the current session to navigate between communities.

    Args:
        session_id (str): The ID of the session to update.
        new_subreddit_id (str): The ID of the subreddit to set as active.

    Returns:
        dict: {
            "success": True,
            "message": str  # Confirmation of subreddit switch
        }
        or
        {
            "success": False,
            "error": str  # Reason for failure (e.g., session or subreddit not found)
        }

    Constraints:
        - The session must exist.
        - The target subreddit must exist in the platform.
        - After switching, the session's active_subreddit reflects the new subreddit.
    """
    if not session_id:
        return { "success": False, "error": "Session ID is required" }

    if not new_subreddit_id:
        return { "success": False, "error": "New subreddit ID is required" }

    if session_id not in self.sessions:
        return { "success": False, "error": "Session does not exist" }

    if new_subreddit_id not in self.subreddits:
        return { "success": False, "error": "Subreddit does not exist" }

    # Update the active subreddit
    self.sessions[session_id]["active_subreddit"] = new_subreddit_id

    return {
        "success": True,
        "message": f"Active subreddit switched to {new_subreddit_id}"
    }

